        getPRDetails: function() { return PR12; },
        fetchDiscussionsAndRawData: function() { return { markdown: '## Threads\n', rawThreads: [] }; }
    }, overrides.gh || {});
    var gitOps = Object.assign({
        checkoutPRBranch: function() {},
        detectMergeConflicts: function() { return []; },
