/**
 * Pre-CLI Test Rework Setup Action (preCliJSAction for pr_test_automation_rework)
 * Same as preCliReworkSetup.js but specifically targets test/{TICKET-KEY} branches,
 * not feature ai/{TICKET-KEY} branches.
 */

var configLoader = require('./configLoader.js');
const gh = require('./common/githubHelpers.js');
const gitOps = require('./common/gitOps.js');
const prHelper = require('./common/pullRequest.js');
const trackersModule = require('./common/trackers.js');
const fetchQuestionsToInput = require('./fetchQuestionsToInput.js');
const fetchLinkedBugsToInput = require('./fetchLinkedBugsToInput.js');

function findTestPRForTicket(scm, ticketKey) {
    try {
        const branchName = 'test/' + ticketKey;
        console.log('Searching for PR on branch:', branchName);

        const openPRs = scm.listPrs('open');
        const openMatch = openPRs.filter(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName;
        });
        if (openMatch.length > 0) {
            console.log('Found open test PR #' + openMatch[0].number);
            return openMatch[0];
        }

        console.warn('No open PR found for test branch:', branchName);
        return null;
    } catch (e) {
        console.error('Failed to find test PR:', e);
        return null;
    }
}

function action(params) {
    var tracker = null;
    try {
        var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
        var inputFolder = actualParams.inputFolderPath;
        var ticketKey = inputFolder.split('/').pop();
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        var scm = configLoader.createScm(config);
        tracker = trackersModule.createTracker(config, actualParams.customParams || (params.jobParams && params.jobParams.customParams) || {});

        console.log('=== Test rework setup for:', ticketKey, '===');

        // Clear stale output files from any previous run so the post-action
        // never reads a result JSON that belongs to a different ticket.
        try {
            cli_execute_command({
                command: 'bash -c "rm -f outputs/test_automation_result.json outputs/story_test_automation_result.json outputs/tracker_comment.md outputs/comment.md outputs/jira_comment.md outputs/response.md outputs/pr_body.md outputs/bug_description.md outputs/failed_description_*.md"'
            });
            console.log('Cleared stale output files before rework');
        } catch (e) {
            console.warn('Could not clear output files:', e);
        }

        // Step 1: GitHub repo info
        var repoInfo = scm.getRemoteRepoInfo();
        if (!repoInfo) {
            const err = 'Could not determine GitHub repository from git remote';
            try { tracker.postComment(ticketKey, 'h3. ❌ Test Rework Setup Failed\n\n' + err); } catch (e) {}
            return { success: false, error: err };
        }

        // Step 2: Find PR on test/{KEY} branch specifically
        var pr = findTestPRForTicket(scm, ticketKey);
        const testBranchName = 'test/' + ticketKey;

        if (!pr) {
            // No open PR — check if the test branch exists on remote
            console.log('No open PR found. Checking if branch exists on remote:', testBranchName);
            var branchExists = false;
            try {
                const lsOutput = cli_execute_command({ command: 'git ls-remote --heads origin ' + testBranchName }) || '';
                branchExists = lsOutput.indexOf('refs/heads/' + testBranchName) !== -1;
            } catch (e) {
                console.warn('Could not check remote branch:', e);
            }

            if (!branchExists) {
                const err = 'No test PR and no remote branch found for ' + testBranchName + '. Moving to Backlog for re-automation.';
                try {
                    tracker.postComment(ticketKey, 'h3. ❌ Test Rework Setup Failed\n\n' + err);
                    tracker.moveToStatus(ticketKey, config.jira.statuses.BACKLOG);
                } catch (e) {}
                return { success: false, error: err };
            }

            // Branch exists — ALWAYS checkout first so CLI runs on correct branch
            // (critical: CLI always runs regardless of preCliJSAction return value)
            try {
                gitOps.checkoutPRBranch(testBranchName, config.workingDir, config.git.baseBranch);
                console.log('✅ Checked out branch:', testBranchName);
            } catch (e) {
                console.warn('Could not checkout branch (will try fetch+checkout):', e);
                try {
                    cli_execute_command({ command: gh.buildOriginFetchCommand(testBranchName + ':' + testBranchName) });
                    cli_execute_command({ command: 'git checkout ' + testBranchName });
                    console.log('✅ Checked out branch via fetch:', testBranchName);
                } catch (e2) {
                    console.warn('Branch checkout failed:', e2);
                }
            }

            console.log('Creating PR for rework from existing branch...');
            try {
                const ticket = tracker.getIssue(ticketKey);
                const summary = ticket && ticket.fields ? (ticket.fields.summary || ticketKey) : ticketKey;
                const prTitle = configLoader.formatTemplate(config.formats.prTitle.rework, {ticketKey: ticketKey, ticketSummary: summary});

                if (!scm.createPr) {
                    throw new Error('Configured SCM provider does not support createPr');
                }
                const prResult = scm.createPr({
                    title: prTitle,
                    // gh-737: merge bot links approved issues via 'Closes #N' —
                    // emit it by construction on this auto-created rework PR.
                    body: prHelper.ensureClosesLine('Auto-created PR for rework of test automation.\n\nTicket: ' + ticketKey, ticketKey),
                    branchName: testBranchName,
                    baseBranch: config.git.baseBranch
                });
                if (!prResult || !prResult.success) {
                    throw new Error((prResult && prResult.error) || 'SCM provider failed to create PR/MR');
                }

                console.log('✅ Created new PR/MR #' + (prResult.number || '?') + ' for rework');
                pr = { number: prResult.number, html_url: prResult.prUrl, head: { ref: testBranchName } };
            } catch (createErr) {
                // PR creation failed — CLI is already on correct branch, postTestReworkResults will create PR
                console.warn('PR auto-creation failed (CLI will run on correct branch, PR will be created post-rework):', createErr.toString());
                try {
                    tracker.postComment(ticketKey, 'h3. ⚠️ PR Auto-Creation Warning\n\nBranch {code}' + testBranchName + '{code} is checked out and rework will proceed.\nA PR will be created automatically after rework completes.\n\nError: ' + createErr.toString());
                } catch (e) {}

                // Write minimal context so CLI knows what to do
                try {
                    const ticket2 = tracker.getIssue(ticketKey);
                    const summary2 = ticket2 && ticket2.fields ? (ticket2.fields.summary || '') : '';
                    gitOps.writePRContext(inputFolder, { number: 0, title: ticketKey + ' ' + summary2, html_url: '' }, '', 'No PR exists yet — re-run tests from scratch on this branch.', []);
                } catch (e) { console.warn('Could not write fallback context:', e); }

                return { success: true, branchName: testBranchName, prNumber: null, noPR: true };
            }
        }

        // Step 3: PR details
        const prDetails = gh.getPRDetails(scm, pr.number);
        if (!prDetails) {
            return { success: false, error: 'Failed to fetch PR details for PR #' + pr.number };
        }

        // Step 4: Checkout test branch
        const branchName = prDetails.head ? prDetails.head.ref : null;
        if (!branchName) {
            return { success: false, error: 'Could not determine bra…

/**
 * Post Test Rework Results Action (postJSAction for pr_test_automation_rework)
 * After cursor agent fixes test issues and re-runs the test:
 * 1. Reads outputs/test_automation_result.json (new test result after fixes)
 * 2. Stages testing/ folder, commits, force-pushes to existing PR branch
 * 3. Replies to and resolves PR review threads (from outputs/review_replies.json)
 * 4. Posts PR comment with fix summary
 * 5. If test passed  → moves to In Review - Passed
 * 6. If test failed  → moves to In Review - Failed (bug may have changed)
 * 7. Posts Jira comment, removes WIP label
 */

var configLoader = require('./configLoader.js');
var autoStart = require('./common/autoStart.js');
var feedbackLoop = require('./common/feedbackLoop.js');
var prHelper = require('./common/pullRequest.js');
var mergeState = require('./common/mergeState.js');
const { GIT_CONFIG, LABELS } = require('./config.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var trackersModule = require('./common/trackers.js');
var commentMarkup = require('./common/commentMarkup.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}


/**
 * Build the "Test Rework Completed" comment in the flavor of the ticket's
 * tracker (gh-770). The template historically hard-coded Jira wiki markup
 * (h3., *bold*, {code}) and was posted via raw jira_post_comment; on a
 * GitHub-backed tracker that renders as raw text garbage.
 *
 * @param {Object} flavor - a commentMarkup flavor bag (forTicket/forFlavor)
 * @param {Object} ctx    - { passed, testStatus, branchName, prUrl, fixSummary }
 * @returns {string} the rendered comment
 */
function buildTestReworkResultComment(flavor, ctx) {
    var m = flavor;
    var statusEmoji = ctx.passed ? '✅' : '❌';
    var comment = m.h(3, '🔧 Test Rework Completed') + '\n\n' +
        m.bold('Re-run result') + ': ' + statusEmoji + ' ' + m.bold(String(ctx.testStatus).toUpperCase()) + '\n' +
        m.bold('Branch') + ': ' + m.inline(ctx.branchName) + '\n';
    if (ctx.prUrl) {
        comment += m.bold('Pull Request') + ': ' + ctx.prUrl + '\n';
    }
    comment += '\n' + ctx.fixSummary;
    return comment;
}

// Canonical copy (gh-823/gh-912): the warning:/note: line filter lives in
// common/pullRequest.js once — this delegate keeps every local call site.
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function readFile(path) {
    try {
        const content = file_read({ path: path });
        return (content && content.trim()) ? content : null;
    } catch (e) {
        console.warn('Could not read file ' + path + ':', e);
        return null;
    }
}

function readResultJson() {
    try {
        const raw = readFile('outputs/test_automation_result.json');
        if (!raw) return null;
        return JSON.parse(raw);
    } catch (e) {
        console.error('Failed to parse test_automation_result.json:', e);
        return null;
    }
}

function findTestPRForTicket(scm, ticketKey) {
    try {
        const branchName = 'test/' + ticketKey;
        const openPRs = scm.listPrs('open') || [];
        const match = openPRs.filter(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName;
        });
        if (match.length > 0) return match[0];
        console.warn('No open test PR found for branch', branchName);
        return null;
    } catch (e) {
        console.error('Failed to find PR:', e);
        return null;
    }
}

function updatePullRequestBody(scm, prNumber, ticketKey, testStatus, bodyContent) {
    if (!bodyContent) return false;

    try {
        const body = '## ' + ticketKey + ' Result: ' + testStatus.toUpperCase() + '\n\n' +
            '**Latest rework result:** `' + testStatus.toUpperCase() + '`\n\n' +
            '---\n\n' + bodyContent;
        if (scm.updatePrBody) {
            scm.updatePrBody(prNumber, body);
            console.log('✅ Updated PR/MR body with latest test rework result');
            return true;
        }
        console.warn('SCM provider does not support updatePrBody — posting summary comment only');
        return false;
    } catch (e) {
        console.warn('Failed to update PR body with latest rework result:', e.message || e);
        return false;
    }
}

/**
 * gh-761: canonical MERGE_HEAD probe (js/common/mergeState.js). The previous
 * local duplicate drifted — it returned true on ANY non-throwing call, so a
 * non-throwing command with empty output read as "merge in progress" and
 * silently skipped rework commits and base-branch merges. The canonical
 * probe requires non-empty output (the merge-head SHA).
 */
function isMergeInProgress() {
    return mergeState.isMergeInProgress(function (command) {
        return cli_execute_command({ command: command });
    });
}

function isSubmodulePath(path) {
    try {
        const stageOutput = cleanCommandOutput(
            cli_execute_command({ command: 'git ls-files --stage -- "' + path + '"' }) || ''
        );
        return stageOutput.split('\n').some(function(line) {
            return line.trim().indexOf('160000 ') !== -1;
        });
    } catch (e) {
        return false;
    }
}

