        }
        return realCli(args);
    };
    // Re-load the module with the failing cli — the module captures the cli at load time.
    var files = { 'outputs/test_automation_result.json': PASSED_RESULT_JSON };
    var fileReadMock = function(args) {
        var p = args && args.path ? args.path : args;
        return files[p] !== undefined ? files[p] : null;
    };
    var moduleExports = loadModule(
        'js/postTestReworkResults.js',
        makeRequire({
            './configLoader.js': {
                loadProjectConfig: function() { return REWORK_ACTION_CONFIG; },
