function makeActionHarnessWithFailingPushVerify() {
    var harness = loadReworkActionHarness({
        files: { 'outputs/test_automation_result.json': PASSED_RESULT_JSON }
    });
    var realCli = harness.cliMock;
    var failingCli = function(args) {
        if (args.command.indexOf('git ls-remote --heads origin') === 0) {
            harness.recorded.cli.push(args.command);
            return 'warning: redirecting to https://git.example.com/\n';
        }
        return realCli(args);
    };
    // Re-load the module with the failing cli — the module captures the cli at load time.
    var files = { 'outputs/test_automation_result.json': PASSED_RESULT_JSON };
    var fileReadMock = function(args) {
        var p = args && args.path ? args.path : args;
        return files[p] !== undefined ? files[p] : null;
    };
    var moduleExports = loadModule(
        'js/postTestReworkResults.js',
        makeRequire({
            './configLoader.js': {
                loadProjectConfig: function() { return REWORK_ACTION_CONFIG; },
                createScm: function() { return harness.scm; },
                formatTemplate: function(t, vars) { return t.split('{ticketKey}').join(vars.ticketKey).split('{result}').join(vars.result); },
                resolveInstructions: function() { return { jobParamPatch: {} }; }
            },
            './config.js': configModule,
            './common/autoStart.js': { triggerConfiguredWorkflowForTicket: function() { return false; }, triggerSmIfIdle: function() {} },
            './common/feedbackLoop.js': {
                runQualityGates: function() { return { success: true }; },
                runPolicyGates: function() { return { success: true }; },
                resumeAgent: function(opts) { harness.recorded.resumeCalls.push(opts); return { attempted: false }; }
            },
            './common/pullRequest.js': prHelperRealForRework,
            './common/mergeState.js': loadModule('js/common/mergeState.js'),
            './common/tokenUsageComment.js': { postTokenUsageComments: function() {}, customParamsOf: function() { return {}; } },
            './common/trackers.js': { createTracker: function() { return harness.tracker; } },
            './common/commentMarkup.js': loadModule('js/common/commentMarkup.js',
                makeRequire({ './ticketKeyShapes.js': loadModule('js/common/ticketKeyShapes.js') }))
        }),
        { cli_execute_command: failingCli, file_read: fileReadMock }
    );
    return { module: moduleExports, recorded: harness.recorded, tracker: harness.tracker, cliMock: failingCli };
}

