suite('postTestReworkResults.createPRIfMissing — characterization (gh-928)', function() {

    function harnessForCreate(deps) {
        var h = loadReworkActionHarness({
            files: {},
            openPrs: deps.openPrs !== undefined ? deps.openPrs : [],
            createPullRequestResult: deps.createPullRequestResult
        });
        return h;
    }

    test('existing open PR on the branch → returned as-is, no creation', function() {
        var h = harnessForCreate({ openPrs: [REWORK_PR12] });

        var pr = h.module.createPRIfMissing(h.scm, 'test/PROJ-123', 'PROJ-123', REWORK_ACTION_CONFIG);

