        assert.equal(m.prMatchesBranch({ head: { ref: 'other' } }, 'test/PROJ-1'), false);
        assert.equal(m.prMatchesBranch({ head: null }, 'test/PROJ-1'), false);
        assert.equal(m.prMatchesBranch({}, 'test/PROJ-1'), false);
    });

